You can customize these string using:

https://day.js.org/docs/en/display/from-now#list-of-breakdown-range
But why they're different with other units by default?

And I tried

```js
dayjs.updateLocale('en', {
  relativeTime: {
    ...dayjs.Ls.en.relativeTime,
    s: 'a second',
    ss: '%d seconds',
  },
});
```

It seems `ss` is not working at all.

And when it comes to 44 seconds, it changes to `1 minute` suddenly. Is that possible to change the threads to real world? We don't need the fuzzification.
Maybe we can add another plugin `relativeTimeStrict` like [`formatDistanceStrict`](https://date-fns.org/v2.10.0/docs/formatDistanceStrict) from `date-fns`.

How do you think?

<img width="537" alt="Screen Shot 2020-03-10 at 3 53 55 PM" src="https://user-images.githubusercontent.com/17680888/76292935-1ce7a080-62eb-11ea-8fc5-d9e2d1685041.png">

We do not support `ss`

What we really need is a duration plugin?
Yes, we can do `s: '%d seconds'`, but it's incorrect for `1 seconds`.

What did you mean with `a duration plugin`?
I see.

You can pass a function then:

https://day.js.org/docs/en/customization/relative-time#additional-token-processing

@iamkun How about add a `strict` option for `relativeTime` plugin?

```ts
// based on https://github.com/iamkun/dayjs/blob/dev/src/plugin/relativeTime/index.js
/// <reference path="./relative-time.shim.d.ts" />
import { ConfigType, Dayjs, PluginFunc, UnitType } from 'dayjs';

export const MS = 'millisecond';
export const S = 'second';
export const MIN = 'minute';
export const H = 'hour';
export const D = 'day';
export const W = 'week';
export const M = 'month';
export const Q = 'quarter';
export const Y = 'year';

export interface RelativeTimeThread {
  l: string;
  r?: number;
  d?: UnitType;
}

export interface RelativeTimeOptions {
  strict?: boolean;
  threads?: RelativeTimeThread[];
}

export const relativeTime: PluginFunc = (
  options: RelativeTimeOptions,
  c,
  d,
  // eslint-disable-next-line sonarjs/cognitive-complexity
) => {
  const proto = c.prototype;
  d.Ls.en.relativeTime = {
    future: 'in %s',
    past: '%s ago',
    s: 'a few seconds',
    m: 'a minute',
    mm: '%d minutes',
    h: 'an hour',
    hh: '%d hours',
    d: 'a day',
    dd: '%d days',
    M: 'a month',
    MM: '%d months',
    y: 'a year',
    yy: '%d years',
  };

  if (options?.strict) {
    Object.assign(d.Ls.en.relativeTime, {
      s: '%d second',
      ss: '%d seconds',
      m: '1 minute',
      h: '1 hour',
      d: '1 day',
      M: '1 month',
      y: '1 year',
    });
  }

  const fromTo = (
    input: ConfigType,
    withoutSuffix: boolean,
    instance: Dayjs,
    isFrom = false,
  ) => {
    // @ts-ignore
    const loc = instance.$locale().relativeTime;
    const T: RelativeTimeThread[] =
      options?.threads || options?.strict
        ? [
            { l: 's', r: 1 },
            { l: 'ss', r: 59, d: S },
            { l: 'm', r: 1 },
            { l: 'mm', r: 59, d: MIN },
            { l: 'h', r: 1 },
            { l: 'hh', r: 23, d: H },
            { l: 'd', r: 1 },
            { l: 'dd', r: 30, d: D },
            { l: 'M', r: 1 },
            { l: 'MM', r: 11, d: M },
            { l: 'y' },
            { l: 'yy', d: Y },
          ]
        : [
            { l: 's', r: 44, d: S },
            { l: 'm', r: 89 },
            { l: 'mm', r: 44, d: MIN },
            { l: 'h', r: 89 },
            { l: 'hh', r: 21, d: H },
            { l: 'd', r: 35 },
            { l: 'dd', r: 25, d: D },
            { l: 'M', r: 45 },
            { l: 'MM', r: 10, d: M },
            { l: 'y', r: 17 },
            { l: 'yy', d: Y },
          ];

    if (!loc.ss) {
      loc.ss = loc.s;
    }

    const Tl = T.length;
    let result;
    let out;
    let isFuture;

    for (let i = 0; i < Tl; i += 1) {
      let t = T[i];
      if (t.d) {
        result = isFrom
          ? d(input).diff(instance, t.d, true)
          : instance.diff(input, t.d, true);
      }
      const abs = Math[options?.strict ? 'floor' : 'round'](Math.abs(result));
      isFuture = result > 0;
      if (abs <= t.r || !t.r) {
        if (abs <= 1 && i > 0) t = T[i - 1]; // 1 minutes -> a minute
        const format = loc[t.l];
        if (typeof format === 'string') {
          out = format.replace('%d', String(abs));
        } else {
          out = format(abs, withoutSuffix, t.l, isFuture);
        }
        break;
      }
    }
    if (withoutSuffix) return out;
    return (isFuture ? loc.future : loc.past).replace('%s', out);
  };
  proto.to = function(input, withoutSuffix) {
    return fromTo(input, withoutSuffix, this, true);
  };
  proto.from = function(input, withoutSuffix) {
    return fromTo(input, withoutSuffix, this);
  };

  // @ts-ignore
  const makeNow = (thisDay: Dayjs) => ('$u' in thisDay ? d.utc() : d());

  proto.toNow = function(withoutSuffix) {
    return this.to(makeNow(this), withoutSuffix);
  };
  proto.fromNow = function(withoutSuffix) {
    return this.from(makeNow(this), withoutSuffix);
  };
};
```

I can raise a PR if you'd like to have this feature.

